import { getUserContext } from '@/lib/supabase/user-context'
import { createClient } from '@/lib/supabase/server'
import { PortalHeader, PortalTable, EmptyState } from '@/components/portal/portal-shell'

export default async function PortalProfilePage() { const context = await getUserContext(); const supabase = await createClient(); const { data: profile } = await supabase.from('profiles').select('student_id').eq('id', context!.userId).maybeSingle(); const { data: links } = await supabase.from('parent_student_links').select('student_id').eq('parent_profile_id', context!.userId); const ids = [...new Set([...(links ?? []).map((x) => x.student_id), ...(profile?.student_id ? [profile.student_id] : [])])]; const { data: students } = ids.length ? await supabase.from('students').select('id,full_name,student_code,guardian_name,guardian_phone').in('id', ids) : { data: [] as any[] }; return <><PortalHeader title="Profile" description="Your ClassPilot portal account and linked student records." /><div className="rounded-xl border border-border bg-card p-5"><dl className="grid gap-5 sm:grid-cols-2"><div><dt className="text-sm text-muted-foreground">Account name</dt><dd className="mt-1 font-medium">{context!.fullName}</dd></div><div><dt className="text-sm text-muted-foreground">Email</dt><dd className="mt-1 font-medium">{context!.email}</dd></div><div><dt className="text-sm text-muted-foreground">Account type</dt><dd className="mt-1 font-medium capitalize">{context!.role}</dd></div><div><dt className="text-sm text-muted-foreground">Organization</dt><dd className="mt-1 font-medium">{context!.organization.name}</dd></div></dl></div><h2 className="mb-3 mt-8 font-display text-lg font-semibold">Linked students</h2>{students?.length ? <PortalTable headers={['Student', 'Code', 'Guardian']} rows={students.map((student) => [student.full_name, student.student_code || '—', student.guardian_name || '—'])} /> : <EmptyState text="No student record is linked to this account yet." />}</> }
